import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Why Goryu","description":"","frontmatter":{},"headers":[],"relativePath":"guide/why-goryu.md","filePath":"guide/why-goryu.md","lastUpdated":1789400487000}'),d={name:"guide/why-goryu.md"};function s(i,e,n,l,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="why-goryu" tabindex="-1">Why Goryu <a class="header-anchor" href="#why-goryu" aria-label="Permalink to &quot;Why Goryu&quot;">​</a></h1><p>Goryu is a batteries-included Go framework for building backends — from simple hand-written REST APIs to AI/LLM services — that is productive for humans and easy for LLMs to generate. It is streaming-first, observable, and secure by default.</p><p>Two things are true at once, and Goryu serves both. Humans still write code, so a plain REST API must stay dead simple to build by hand, with Rails/Phoenix ergonomics. And Go is also where people build AI/LLM backends — gateways, agent servers, inference proxies — so Goryu ships the primitives those need as batteries.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>The Go ecosystem has excellent routers, but no Rails/Phoenix-style, batteries-included framework that carries you all the way to production. You assemble the router, validation, error handling, logging, health checks, metrics, and graceful shutdown yourself.</p><p>Building an AI/LLM backend is worse. Today that means hand-rolling the same infrastructure over and over:</p><ul><li><strong>SSE / streaming</strong> token responses, wired correctly with flushing and backpressure.</li><li><strong>Token and cost metering</strong> per request, with per-key and per-token budgets.</li><li><strong>Prompt-keyed response caching</strong> — caching <code>POST</code> bodies, not URLs.</li><li><strong>Provider proxying</strong> for upstream LLM APIs, streamed through to the client.</li><li><strong>Eval recording</strong> to capture request/response pairs for offline evaluation.</li></ul><p>None of this is novel, but every team rebuilds it, and gets the edge cases wrong.</p><h2 id="what-goryu-gives-you" tabindex="-1">What Goryu Gives You <a class="header-anchor" href="#what-goryu-gives-you" aria-label="Permalink to &quot;What Goryu Gives You&quot;">​</a></h2><p>Out of the box, with <code>goryu.New()</code>, you get health checks, metrics, structured logging, and graceful shutdown — no setup. A handler is just a function, and typed input with validation is one call (<code>goryu.Bind[T]</code>).</p><p>When you need them — and only then — the AI primitives are there:</p><ul><li><strong>First-class streaming</strong>: <code>c.SSE(...)</code> and <code>c.Stream(...)</code>, plus typed streaming JSON (<code>goryu.StreamJSON[T]</code>, <code>goryu.SSEJSON[T]</code>) and a WebSocket helper (<code>websocket.Upgrade</code>).</li><li><strong><a href="/middleware/aimeter">Token &amp; cost metering</a></strong>: <code>middleware/aimeter</code> — per-key/per-token rate limiting and USD cost accounting.</li><li><strong><a href="/middleware/promptcache">Prompt cache</a></strong>: <code>middleware/promptcache</code> — body-keyed response caching for LLM endpoints, plus a streaming reverse-proxy helper (<code>aiproxy</code>).</li><li><strong><a href="/middleware/recorder">Eval recording</a></strong>: <code>middleware/recorder</code> — capture request/response pairs as NDJSON for eval datasets.</li><li><strong>LLM-friendly DX</strong>: <code>llms.txt</code> and a machine-readable API reference (<code>App.MountLLMs</code>), an MCP server (<code>goryu mcp</code>), and AI scaffolds (<code>goryu scaffold ai &lt;name&gt; --kind=chat|rag|agent</code>).</li></ul><p>These are additive. A hand-written REST app never pays for AI features it does not use.</p><h2 id="how-goryu-compares" tabindex="-1">How Goryu Compares <a class="header-anchor" href="#how-goryu-compares" aria-label="Permalink to &quot;How Goryu Compares&quot;">​</a></h2><p>Goryu is not &quot;just another fast router&quot; — Gin, Fiber, Echo, and Chi own that space. Goryu&#39;s edge is being genuinely great for <strong>both</strong> a plain REST service and an AI backend, without making the simple case complicated.</p><table tabindex="0"><thead><tr><th></th><th>Goryu</th><th>Gin</th><th>Fiber</th><th>Echo</th><th>Chi</th></tr></thead><tbody><tr><td>Fast router</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Batteries-included (health, metrics, logging, graceful shutdown)</td><td>Yes</td><td>No</td><td>Partial</td><td>Partial</td><td>No</td></tr><tr><td>CLI + scaffolding</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Streaming-first (SSE, typed streaming, WebSocket)</td><td>Yes</td><td>Manual</td><td>Manual</td><td>Manual</td><td>Manual</td></tr><tr><td>Built-in token/cost metering</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Prompt-keyed cache + provider proxy</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Eval recording</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Secure by default (on every response path)</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>LLM-friendly (<code>llms.txt</code>, MCP server)</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td></tr></tbody></table><p>The honest summary: for a plain REST API, Goryu is as fast as Gin with far more built in. For an AI backend, the pieces you would otherwise hand-roll are already batteries — and the simple case stays simple.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>The simple case stays simple</strong> — a hand-written REST API must never pay for AI features it doesn&#39;t use.</li><li><strong>Built for humans first; friendly to LLMs second</strong> — the same clean API serves both.</li><li><strong>Secure by default, on every response path.</strong></li><li><strong>Streaming is a first-class citizen, not an afterthought.</strong></li><li><strong>The core stays small and stable; breadth lives in contrib.</strong></li><li><strong>If an LLM can&#39;t reliably generate correct Goryu code, the API is too clever.</strong></li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/guide/getting-started">Getting Started</a> — install Goryu and build your first service.</li><li><a href="/ai/">AI backends</a> — streaming, metering, caching, proxying, and recording.</li><li><a href="/security/">Security</a> — RBAC, audit logging, and secure-by-default defaults.</li><li><a href="/streaming/">Streaming</a> — SSE, typed streaming JSON, and WebSockets.</li></ul>',21)])])}const p=t(d,[["render",s]]);export{g as __pageData,p as default};
